window.RP_SESSION={"id":"S-e37297ab4b6c","messages":[{"id":"RP-II-0201633","time":"2026-09-22T03:33:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201634","time":"2026-09-22T03:33:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201635","time":"2026-09-22T03:33:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"...","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201636","time":"2026-09-22T03:34:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201637","time":"2026-09-22T03:35:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"부러진 팔이 욱씬욱씬욱씬-","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201638","time":"2026-09-22T03:35:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"모나님 ─. 여기 계실까요?\"\n\n:: 타박타박, 두리번 거리며 모나를 찾습니다. 품 안에는 소중히, 딜라일라가 준 포션을 들고서 말이죠.","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201639","time":"2026-09-22T03:35:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"오아..? 라이티티아 씨..?\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201640","time":"2026-09-22T03:36:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"아..! 모나님, 여기 계셨군요. 팔은...좀, 어떠세요...? 많이 아프시죠...?\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201641","time":"2026-09-22T03:36:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"아...아뇨..! 저는..괜찮아얏..! 요...!\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201642","time":"2026-09-22T03:37:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":":: 아하하...조금은 어색하게 웃습니다. 길드의 모든 분들은, 다들 다쳤어도 안다쳤다고 하는게 습관이신걸까요?","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201643","time":"2026-09-22T03:37:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"하지만 아무래도 숨기기엔 너무 큰 통증인가 보네요.","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201644","time":"2026-09-22T03:38:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"... ...많이 아프시잖아요. 이거, 드세요.\"\n\n:: 그래도, 다행이에요. 포션이라도 드릴 수 있어서요. 조금이라도, 모나님이 아프지 않으신게 중요하니까요. \n\n포션을 열어, 당신에게 내밉니다.","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201645","time":"2026-09-22T03:38:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"딜라일라님이 구해오셨어요, 다행이죠...\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201646","time":"2026-09-22T03:38:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"파리해진 안색에 송골송골 맺힌 식은 땀, 멈추질 않은 떨림.","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201647","time":"2026-09-22T03:39:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"아, 그래요..? 나중에 딜라이라 씨에게 감사인사...드려야겠어요..!\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201648","time":"2026-09-22T03:39:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"모나는 굳이 사양하지 않습니다. 자신의 아픈 모습에 동료들이 걱정하는 건 보고 싶지 않거든요. 그러니 약이 있다면 먹어야죠!","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201649","time":"2026-09-22T03:39:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"후후..그래요. 그래도, 지금은 모나님이 괜찮아지시는게 먼저니까요. ...이럴줄 알았다면, 아까 그 포션들도 조금 남겨둘 걸 그랬어요...\"\n\n:: 자신이 두개를 다 먹는게 아니었는데 말이에요.","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201650","time":"2026-09-22T03:40:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"꼴깍꼴깍-","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201651","time":"2026-09-22T03:41:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"휴...! 아니에요. 그때 라이티티아 씨가 조금이라도 회복 됐으니, 그 사슴 괴물을 몰아낼 수 있었던걸요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201652","time":"2026-09-22T03:41:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"...전, 그리 도움이 되지 못했는걸요...\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201653","time":"2026-09-22T03:42:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"제가 도와달라 외쳤고, 그래서 도와주셨잖아요? 정말로 고마워요\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201654","time":"2026-09-22T03:43:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"...모나님은, 정말. 다정하신 분이세요. 후후...\"\n\n:: 연약한 자신을 불사르려 해도, 불사르고 강인한 자신을 키우는것에도 ─. 오랜 시간이 걸릴테죠. 이제 막 씨앗을 심었을테니, 꽃이 피울때까지 노력해야한다는건 알지만...조금은, 무력한 자신이 싫어지네요. \n\n\"그래도, 좀 나아지셨나요?\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201655","time":"2026-09-22T03:43:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"모나 얼마나 나아졌을까요","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201656","time":"2026-09-22T03:43:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"체력 한번 굴려보까요?","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201657","time":"2026-09-22T03:43:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"구러며눈?","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201658","time":"2026-09-22T03:43:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201659","time":"2026-09-22T03:44:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'모나 델핀'의 체력 판정 :\n[5] + [1] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0201660","time":"2026-09-22T03:44:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"분쇄골절은 아무래도 분쇄골절인것이지비...","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201661","time":"2026-09-22T03:44:00+09:00","room":"RP II","name":"델타인","profile":"델타인","identity":"unresolved","type":"dialogue","body":"후유증이 남을 것이다. 모나…!","characters":[]},{"id":"RP-II-0201662","time":"2026-09-22T03:44:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그래도 이 정도면 통증을 버틸 수 있는 수준이겠네요!","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201663","time":"2026-09-22T03:44:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그러니","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201664","time":"2026-09-22T03:44:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"이제 돌아감ㄴ 청소 빨래 설거지를 해라 띠띠","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201665","time":"2026-09-22T03:45:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"조아요 제가 맡도록하죠","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201666","time":"2026-09-22T03:45:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"아픈건 많이 나아진 것 같아요..!\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201667","time":"2026-09-22T03:45:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"...그나마, 다행이에요. 그래도, 너무 무리하지는 마세요. 아직 다 나으신건 아닐테니까요.\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201668","time":"2026-09-22T03:46:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"네. 아무래도 그러는 게 좋겠죠오?\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201669","time":"2026-09-22T03:46:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":":: 꾸닥.\n\"포션은, 최대한 빨리 드리는게 나을 듯 해서...급하게 온거였으니까, 푹 쉬세요. 모나님.\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201670","time":"2026-09-22T03:46:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"...그래도, 금방. 집으로 돌아갈 수 있을테니까요.\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201671","time":"2026-09-22T03:47:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"라이티티아 씨도 무리하지 마시구요. 라이티티아 씨도 다치셨잖아요?\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201672","time":"2026-09-22T03:47:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"...후후, 저야. 포션을 두개나 먹어버렸는걸요. 괜찮아요. 금방 나을거랍니다.\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201673","time":"2026-09-22T03:47:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"제 몸은 제가 잘 아니까...지금은, 거의 안아파요. 걱정마세요!\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201674","time":"2026-09-22T03:48:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":":: 방긋 웃으며 고개를 끄덕입니다. 통증은 있지만, 이정도는 충분히 넘길 수 있으니까요. 모두를 지켜보기만 해야하는건 싫어요. 조금의 욕심인거죠.","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201675","time":"2026-09-22T03:48:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"안돼요. 보통 그렇게 말하는 분들일 수록 쉬어야 하는 분들이에요.\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201676","time":"2026-09-22T03:48:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"... ...아하하...모나님은, 꽤나 단호하신 부분이 있네요...\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201677","time":"2026-09-22T03:49:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"...저도, 쉴거랍니다! 모나님에게, 포션은 빨리 드려야할 듯 해서...저도 이제 쉬러 갈 생각이에요.\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201678","time":"2026-09-22T03:49:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"\"네, 그러면 푹 쉬어요 라이티티아 씨. 카사 씨도요..!\"","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201679","time":"2026-09-22T03:49:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201680","time":"2026-09-22T03:49:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":"\"...후후, 카사도 챙겨주셔서 감사해요. 모나님도, 푹 쉬세요. 좋은꿈 꾸시구요.\"","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201681","time":"2026-09-22T03:49:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"reviewed","type":"dialogue","body":":: 살짝 허리를 숙여 인사하곤, 돌아갑니다. 챱챱.","characters":["P-fae6af716ea2"]},{"id":"RP-II-0201682","time":"2026-09-22T03:50:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그렇게 모나는 돌아가는 라이티티아의 뒷 모습을 바라보다가...","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201683","time":"2026-09-22T03:51:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"멍하니 밤하늘을 올려다봅니다.","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201684","time":"2026-09-22T03:54:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"잘 자라, 잘 자라 예쁜 아가야\n달빛이 너에게 인사를 건네면\n구름 마차가 살며시 찾아와\n꿈의 무도회로 너를 초대할 거야\n\n잘 자라, 잘 자라 사랑하는 아가야\n별님과 함께 마음껏 춤추렴\n혹시 돌아오는 길 잃지 않도록\n엄마가 너의 이름을 불러 줄게","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201685","time":"2026-09-22T03:54:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"누구를 위한 자장가인지는 모르겠지만...","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201686","time":"2026-09-22T03:56:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"이름도 얼굴도 모를 엄마 잃은 아이가, 부디 저 밤하늘 별의 바다에서 그토록 보고싶어 하던 엄마를 만났기를.","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201687","time":"2026-09-22T03:56:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"그렇게 기도하며 조용히 자장가를 부릅니다.","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201688","time":"2026-09-22T03:56:00+09:00","room":"RP II","name":"모나 델핀","profile":"모나 델핀","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-48cca58d02b2"]},{"id":"RP-II-0201689","time":"2026-09-22T03:56:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]},{"id":"RP-II-0201690","time":"2026-09-22T10:41:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"unresolved","type":"dialogue","body":"!독백","characters":[]},{"id":"RP-II-0201691","time":"2026-09-22T10:41:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"조용히, 피어오르는\n또 다른 누군가의 이야기.\n\n※해당 RP는 중참이 불가합니다.\n※중참 희망시 해당 기입자께 문의 바랍니다.","characters":[]}]};
